import{z as i,x as B,o as r,c as d,q as o,j as s,D as t,d as a,s as l,S as n,b as e}from"./chunks/framework.C8m1ZpeB.js";const m=JSON.parse('{"title":"行级安全","description":"","frontmatter":{"title":"行级安全","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/row-level-security.md","filePath":"cs/row-level-security.md","lastUpdated":1791063341000}'),p={name:"cs/row-level-security.md"};function C(S,E,D,c,F,L){const A=B("Mermaid");return r(),d("div",null,[E[2]||(E[2]=o('<h1 id="行级安全" tabindex="-1">行级安全 <a class="header-anchor" href="#行级安全" aria-label="Permalink to &quot;行级安全&quot;">​</a></h1><div class="epigraph"><p>视图和授权若只到表，租户仍能看见别人的行。行级策略把谓词接到扫描上，使「当前用户」成为计划的一部分。</p><footer>—— 据 PostgreSQL RLS；关系系统安全视图传统</footer></div><p><a href="/cs/jepsen-testing">上一课</a>查隔离是否撒谎。缺口是<strong>谁被允许看见哪一行</strong>：隔离正确仍可能越权。本课钉行级安全；审计下一课记谁读过。不把 RLS 写成密码学。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><code>GRANT SELECT ON t</code> 太粗。RLS：对表附策略，<code>USING</code> 谓词在查询里合取。缺口是计划：策略必须稳定、可下推，否则每行调函数会打爆 OLTP。超级用户绕过、BYPASSRLS、安全定义者函数是常见洞。多租户用 <code>tenant_id = current_setting(...)</code> 必须防会话被改。</p><p><span class="marginnote">术语翻译：RLS（行级安全）就是「数据库在每条查询外自动包一层 WHERE」的手段来做按行授权的事——表权限照常放行，策略谓词再决定哪些行真正可见，应用代码一行不用改。</span></p><p><span class="marginnote">强制访问与自主访问不同。RLS 默认是自主的、可绕过的，除非角色设计把绕过封死。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>策略尽量用列与会话变量，避免每行查外表。测试：同一 SQL 换角色看行数。与视图：视图可漏 WITH CHECK。与审计：绕过事件也要记。与 TPC：基准角色通常是全能用户，测不出 RLS。</p>',9)),(r(),s(n,null,{default:t(()=>[l(A,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E6%9F%A5%E8%AF%A2%22%5D%20--%3E%20P%5B%22%E7%AD%96%E7%95%A5%E8%B0%93%E8%AF%8D%22%5D%0A%20%20P%20--%3E%20SCAN%5B%22%E6%89%AB%E6%8F%8F%20%2F%20%E7%B4%A2%E5%BC%95%22%5D%0A%20%20ROLE%5B%22%E8%A7%92%E8%89%B2%22%5D%20--%3E%20P%0A"})]),fallback:t(()=>[...E[0]||(E[0]=[a(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e("h2",{id:"机制",tabindex:"-1"},[a("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=e("p",null,[a("策略是查询改写：计划里多一个滤子。索引能否服务该滤子决定 OLTP 能否活。漏 WITH CHECK 会让 "),e("code",null,"INSERT"),a(" 写进自己看不见的行。计划缓存必须按角色分键，否则串计划泄密或用管理员统计估错租户选择率。CDC 与复制槽通常绕过 RLS，权限要单开。向量/搜索侧过滤必须在 ANN 前或保证租户隔离，否则跨租户召回。")],-1)),E[5]||(E[5]=e("p",null,"带 RLS 的查询被改写与常见的两条失效路径：",-1)),(r(),s(n,null,{default:t(()=>[l(A,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20APP%5B%22%E7%A7%9F%E6%88%B7%E5%8F%91%E6%9D%A5%20SELECT%22%5D%20--%3E%20B%7B%22%E8%A7%92%E8%89%B2%E5%B8%A6%20BYPASSRLS%20%E6%88%96%E8%B6%85%E7%BA%A7%E7%94%A8%E6%88%B7%EF%BC%9F%22%7D%0A%20%20B%20--%3E%7C%22%E6%98%AF%22%7C%20ALL%5B%22%E7%AD%96%E7%95%A5%E4%B8%8D%E7%94%9F%E6%95%88%EF%BC%8C%E8%A7%81%E5%85%A8%E8%A1%A8%22%5D%0A%20%20B%20--%3E%7C%22%E5%90%A6%22%7C%20RW%5B%22%E6%9F%A5%E8%AF%A2%E6%94%B9%E5%86%99%EF%BC%9A%E8%BF%BD%E5%8A%A0%E7%AD%96%E7%95%A5%E8%B0%93%E8%AF%8D%22%5D%0A%20%20RW%20--%3E%20IDX%7B%22%E8%B0%93%E8%AF%8D%E8%83%BD%E8%B5%B0%E7%B4%A2%E5%BC%95%EF%BC%9F%22%7D%0A%20%20IDX%20--%3E%7C%22%E8%83%BD%22%7C%20FAST%5B%22%E7%B4%A2%E5%BC%95%E6%89%AB%E6%8F%8F%EF%BC%8C%E5%8F%AA%E8%A7%A6%E6%9C%AC%E7%A7%9F%E6%88%B7%E8%A1%8C%22%5D%0A%20%20IDX%20--%3E%7C%22%E4%B8%8D%E8%83%BD%22%7C%20SLOW%5B%22%E9%80%90%E8%A1%8C%E8%BF%87%E6%BB%A4%EF%BC%8COLTP%20%E5%8F%97%E6%8D%9F%22%5D%0A%20%20RW%20--%3E%20W%7B%22%E5%86%99%E6%93%8D%E4%BD%9C%E9%85%8D%20WITH%20CHECK%EF%BC%9F%22%7D%0A%20%20W%20--%3E%7C%22%E6%BC%8F%E9%85%8D%22%7C%20LEAK%5B%22%E5%8F%AF%E5%86%99%E5%85%A5%E8%87%AA%E5%B7%B1%E7%9C%8B%E4%B8%8D%E8%A7%81%E7%9A%84%E8%A1%8C%22%5D%0A"})]),fallback:t(()=>[...E[1]||(E[1]=[a(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=o('<p><span class="marginnote">常见误区：初学者容易以为应用层拼好 WHERE 就等于 RLS。实际上只要角色对基表有 SELECT 权限，绕过应用直连数据库就能看全表；RLS 的滤子在数据库内核里强制生效，不依赖调用者自觉。</span></p><p>超级用户、BYPASSRLS、SECURITY DEFINER 函数是绕过面。物化视图与 FDW 也可能漏策略。会话变量若可被租户 <code>SET</code>，策略等于没有。</p><p><span class="marginnote">为什么重要：策略右侧若写 <code>current_setting(&#39;app.tenant&#39;)</code>，而这个会话变量租户自己能 SET，他就把租户号改成别人的，谓词反过来忠实替他过滤出别人的数据——授权链最脆的一环在变量写权限上。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不设计某云产品的 IAM。下一课审计是责任链，RLS 是强制滤子。不要靠 RLS 替代加密或 TDE。TPC 基准角色通常全能，测不出策略。</p><p>后课默认：多租户用强制行谓词且可下推。应用层 WHERE 不是 RLS——有基表权限就会绕过。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>RLS 把授权谓词合进扫描；计划与绕过路径是漏洞面。</li><li>会话变量必须不可被租户改写；缓存按角色隔离。</li><li>数据库审计下一课。</li><li>出处：PostgreSQL RLS；安全视图传统。</li></ul>',8))])}const u=i(p,[["render",C]]);export{m as __pageData,u as default};
